/**
 * Determines if a {@link Trip} exists whose date range overlaps the given Trip's date range.
 *
 * @param trip The Trip whose date range is checked against all existing trips.
 * @param excludeId The id of a Trip to exclude from the check; can be null. This is used when
 *                  editing an existing Trip so the Trip isn't compared against itself.
 * @return True if an overlapping Trip exists; false otherwise.
 */
public static boolean tripExists(Trip trip, UUID excludeId) {
    if (trip == null)
        return false;

    ArrayList<UserDefineObject> trips = getTrips();

    for (UserDefineObject object : trips) {
        // a Trip can't overlap itself; this happens when editing an existing Trip
        if (excludeId != null && excludeId.equals(object.getId()))
            continue;

        if (trip.overlapsTrip((Trip)object))
            return true;
    }

    return false;
}

